function validate([node, head]) {
  if (!Array.isArray(head) || head.length < 1 || head.length > 500) return 'The list needs 1 to 500 nodes.';
  if (head.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Node values are integers from 1 to 1000.';
  if (new Set(head).size !== head.length) return 'Node values must be distinct.';
  if (!Number.isInteger(node) || !head.includes(node)) return 'node must be the value of a node in the list.';
  return null;
}

