function adapt(input, solve, kit) {
  const [node, head] = input;
  class Node {
    constructor(val) { this.val = val; this.prev = null; this.next = null; }
  }
  // Link the values into a doubly linked list.
  const nodes = head.map(value => new Node(value));
  for (let i = 0; i + 1 < nodes.length; i++) {
    nodes[i].next = nodes[i + 1];
    nodes[i + 1].prev = nodes[i];
  }
  const links = nodes.map(item => [item.val, item.prev, item.next]);
  const result = solve(nodes.find(item => item.val === node));
  const intact = nodes.every((item, i) => item.val === links[i][0] && item.prev === links[i][1] && item.next === links[i][2]);
  if (!intact) throw new Error('The list must not be modified.');
  if (result === undefined) throw new Error('The solution did not return a value.');
  if (!Array.isArray(result)) throw new Error('Return an array of the values.');
  return result;
}

