function toArray(node) {
  // Read the part before node backwards, then the rest forwards, and join them.
  const before = [];
  for (let walk = node.prev; walk !== null; walk = walk.prev) before.push(walk.val);
  const after = [];
  for (let walk = node; walk !== null; walk = walk.next) after.push(walk.val);
  return before.reverse().concat(after);
}

