function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 400 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 8);
  // Draw n distinct values from 1..1000 with a partial shuffle.
  const pool = Array.from({ length: 1000 }, (_, i) => i + 1);
  for (let i = 0; i < n; i++) {
    const j = i + Math.floor(rand() * (1000 - i));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  const head = pool.slice(0, n);
  const pick = rand();
  const index = pick < 0.2 ? 0 : pick < 0.4 ? n - 1 : Math.floor(rand() * n);
  return [head[index], head];
}
